//! Process confinement for `graft run` (ADR 0014).
//!
//! A [`Policy`] lists the directories a confined process may write to; it
//! may read anything. On Linux the policy is enforced with Landlock by
//! [`confine_self`], which `graft` calls in a helper process just before it
//! `exec`s the command. On macOS `seatbelt_command` (macOS only) wraps the command in
//! `sandbox-exec` with a profile generated by `seatbelt_profile`.
//!
//! [`IgnoreInterrupts`] keeps `graft run` alive while the command it
//! started handles Ctrl-C itself.
//!
//! It is one of the two crates allowed to contain `unsafe` (AGENTS.md §6).
//! `unsafe` is denied at the crate root and allowed only in the `signals`
//! module, each block with a `SAFETY` comment.

#![deny(unsafe_code)]

mod signals;

pub use signals::IgnoreInterrupts;

use std::path::{Path, PathBuf};

/// Device files every process may write to, whatever the policy.
#[cfg_attr(not(any(target_os = "linux", test)), allow(dead_code))]
const DEVICE_FILES: &[&str] = &[
    "/dev/null",
    "/dev/zero",
    "/dev/full",
    "/dev/tty",
    "/dev/ptmx",
];

/// Errors from building or applying a policy.
#[derive(Debug, thiserror::Error)]
#[non_exhaustive]
pub enum SandboxError {
    /// A writable path could not be resolved.
    #[error("sandbox path {}: {source}", path.display())]
    Path {
        /// The path as given.
        path: PathBuf,
        /// Why it could not be resolved.
        #[source]
        source: std::io::Error,
    },
    /// A writable path is not absolute.
    #[error("sandbox path {} must be absolute", path.display())]
    Relative {
        /// The path as given.
        path: PathBuf,
    },
    /// The kernel enforces no Landlock restriction.
    #[error(
        "this kernel does not enforce Landlock, so `graft run` cannot confine the command; \
         it needs Linux 5.13 or later with Landlock enabled (`landlock` in /sys/kernel/security/lsm, \
         or `lsm=landlock,...` on the kernel command line)"
    )]
    Unsupported,
    /// Landlock refused the policy.
    #[error("applying the Landlock policy: {0}")]
    Landlock(String),
    /// This platform has no confinement mechanism.
    #[error("graft run cannot confine commands on this platform")]
    Platform,
}

/// Result alias using [`SandboxError`].
pub type Result<T, E = SandboxError> = std::result::Result<T, E>;

/// What a confined process may write to.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Policy {
    writable: Vec<PathBuf>,
    create_only: Vec<PathBuf>,
    tag: Option<String>,
}

impl Policy {
    /// A policy allowing writes below each of `paths` (directories or
    /// files), which must exist. Each is canonicalised, so the policy names
    /// what the kernel will check.
    ///
    /// # Errors
    ///
    /// [`SandboxError::Relative`] or [`SandboxError::Path`].
    pub fn new<P: AsRef<Path>>(paths: impl IntoIterator<Item = P>) -> Result<Self> {
        let mut writable = Vec::new();
        for p in paths {
            let p = p.as_ref();
            if !p.is_absolute() {
                return Err(SandboxError::Relative { path: p.to_owned() });
            }
            let canonical = p.canonicalize().map_err(|source| SandboxError::Path {
                path: p.to_owned(),
                source,
            })?;
            if !writable.contains(&canonical) {
                writable.push(canonical);
            }
        }
        Ok(Self {
            writable,
            create_only: Vec::new(),
            tag: None,
        })
    }

    /// Also allows adding files below each of `dirs` (which must exist),
    /// but, where the platform can tell the difference, not changing or
    /// removing the files already there: for git's object store, where git
    /// only ever writes a temporary file (`tmp_*`) and links it into place.
    ///
    /// Seatbelt (macOS) enforces exactly that. Landlock (Linux) cannot: a
    /// rename needs the right to remove files, and permission bits are not
    /// a Landlock right, so there it grants creating, writing, renaming
    /// and removing files and directories (not truncating, symlinks or
    /// device files).
    ///
    /// # Errors
    ///
    /// As [`Self::new`].
    pub fn with_create_only<P: AsRef<Path>>(
        mut self,
        dirs: impl IntoIterator<Item = P>,
    ) -> Result<Self> {
        for p in Self::new(dirs)?.writable {
            if !self.create_only.contains(&p) {
                self.create_only.push(p);
            }
        }
        Ok(self)
    }

    /// The canonical create-only directories, in the order given.
    #[must_use]
    pub fn create_only(&self) -> &[PathBuf] {
        &self.create_only
    }

    /// Marks every denial under this policy with `tag` where the platform
    /// can (Seatbelt logs it with each denied write), so a run's own
    /// denials can be told apart from other processes'. `tag` should be
    /// unique per run; characters other than ASCII letters, digits, `-`
    /// and `_` are dropped.
    #[must_use]
    pub fn tagged(mut self, tag: &str) -> Self {
        let clean: String = tag
            .chars()
            .filter(|c| c.is_ascii_alphanumeric() || *c == '-' || *c == '_')
            .collect();
        self.tag = (!clean.is_empty()).then_some(clean);
        self
    }

    /// The tag set by [`Self::tagged`].
    #[must_use]
    pub fn tag(&self) -> Option<&str> {
        self.tag.as_deref()
    }

    /// The canonical writable paths, in the order given.
    #[must_use]
    pub fn writable(&self) -> &[PathBuf] {
        &self.writable
    }
}

/// How well [`confine_self`] could enforce the policy.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Enforcement {
    /// Every write right required by Graft is restricted. Newer optional
    /// Landlock rights are enforced when the kernel supports them.
    Full,
    /// The kernel cannot enforce all required write rights.
    Partial {
        /// Required rights that the kernel does not support.
        missing: &'static str,
    },
}

#[cfg(target_os = "linux")]
fn enforcement_for_abi(abi: landlock::ABI) -> Result<Enforcement> {
    use landlock::ABI;

    match abi {
        ABI::Unsupported => Err(SandboxError::Unsupported),
        ABI::V1 => Ok(Enforcement::Partial {
            missing: "Refer (cross-directory rename permissions) and Truncate (file truncation)",
        }),
        ABI::V2 => Ok(Enforcement::Partial {
            missing: "Truncate (file truncation)",
        }),
        _ => Ok(Enforcement::Full),
    }
}

/// Which mechanism this platform would use, and whether it looks usable.
/// For `graft doctor`; [`confine_self`] reports the definitive answer.
pub fn mechanism() -> (&'static str, Result<(), String>) {
    #[cfg(target_os = "linux")]
    {
        let lsm = std::fs::read_to_string("/sys/kernel/security/lsm");
        let ok = match lsm {
            Ok(list) if list.trim().split(',').any(|m| m == "landlock") => Ok(()),
            Ok(list) => Err(format!(
                "landlock is not in the active LSMs ({})",
                list.trim()
            )),
            Err(e) => Err(format!("cannot read /sys/kernel/security/lsm: {e}")),
        };
        ("landlock", ok)
    }
    #[cfg(target_os = "macos")]
    {
        let ok = if Path::new(SANDBOX_EXEC).is_file() {
            Ok(())
        } else {
            Err(format!("{SANDBOX_EXEC} is missing"))
        };
        ("seatbelt", ok)
    }
    #[cfg(not(any(target_os = "linux", target_os = "macos")))]
    {
        ("none", Err("unsupported platform".to_owned()))
    }
}

/// Restricts the current process (and every process it starts) to the
/// policy, with the best Landlock ABI the kernel has. Call it in a
/// single-threaded process right before `exec`.
///
/// # Errors
///
/// [`SandboxError::Unsupported`] if the kernel enforces nothing, and
/// [`SandboxError::Landlock`] or [`SandboxError::Path`] if the policy
/// cannot be applied.
#[cfg(target_os = "linux")]
pub fn confine_self(policy: &Policy) -> Result<Enforcement> {
    use landlock::{
        ABI, AccessFs, PathBeneath, PathFd, Ruleset, RulesetAttr, RulesetCreatedAttr, RulesetStatus,
    };
    let abi = ABI::V6;
    let write = AccessFs::from_write(abi);
    let file_write = write & AccessFs::from_file(abi);
    let mut targets: Vec<(&Path, _)> = policy
        .writable()
        .iter()
        .map(|p| (p.as_path(), if p.is_dir() { write } else { file_write }))
        .collect();
    // See `Policy::with_create_only` for why this is broader than on macOS.
    let create = AccessFs::WriteFile
        | AccessFs::RemoveFile
        | AccessFs::RemoveDir
        | AccessFs::MakeReg
        | AccessFs::MakeDir
        | AccessFs::Refer;
    for p in policy.create_only() {
        targets.push((p.as_path(), create & write));
    }
    for dev in DEVICE_FILES.iter().map(Path::new).filter(|d| d.exists()) {
        targets.push((dev, file_write));
    }
    if Path::new("/dev/pts").is_dir() {
        targets.push((Path::new("/dev/pts"), file_write));
    }
    let mut rules = Vec::new();
    for (path, access) in targets {
        let fd = PathFd::new(path)
            .map_err(|e| SandboxError::Landlock(format!("{}: {e}", path.display())))?;
        rules.push(Ok::<_, landlock::RulesetError>(PathBeneath::new(
            fd, access,
        )));
    }
    let ll = |e: landlock::RulesetError| SandboxError::Landlock(e.to_string());
    let ruleset = Ruleset::default()
        .handle_access(write)
        .map_err(ll)?
        .create()
        .map_err(ll)?
        .add_rules(rules)
        .map_err(ll)?;
    let status = ruleset.restrict_self().map_err(ll)?;
    match status.ruleset {
        RulesetStatus::FullyEnforced => Ok(Enforcement::Full),
        RulesetStatus::PartiallyEnforced => enforcement_for_abi(status.landlock.into()),
        RulesetStatus::NotEnforced => Err(SandboxError::Unsupported),
    }
}

/// `confine_self` exists only on Linux.
///
/// # Errors
///
/// Always [`SandboxError::Platform`].
#[cfg(not(target_os = "linux"))]
pub fn confine_self(_policy: &Policy) -> Result<Enforcement> {
    Err(SandboxError::Platform)
}

/// The macOS sandbox launcher.
#[cfg(any(target_os = "macos", test))]
pub const SANDBOX_EXEC: &str = "/usr/bin/sandbox-exec";

/// A Seatbelt string literal.
#[cfg(any(target_os = "macos", test))]
fn sbpl_string(path: &Path) -> String {
    let mut s = String::from("\"");
    for c in path.to_string_lossy().chars() {
        if matches!(c, '"' | '\\') {
            s.push('\\');
        }
        s.push(c);
    }
    s.push('"');
    s
}

/// The Seatbelt profile for `policy`: anything is allowed except writing
/// to files outside the writable paths and the terminal devices.
#[cfg(any(target_os = "macos", test))]
#[must_use]
pub fn seatbelt_profile(policy: &Policy) -> String {
    use std::fmt::Write as _;
    let mut p = String::from("(version 1)\n(allow default)\n");
    match policy.tag() {
        // The message is logged with each denial (`log show`), which is how
        // `graft run` finds its own.
        Some(tag) => {
            let _ = writeln!(p, "(deny file-write* (with message \"{tag}\"))");
        }
        None => p.push_str("(deny file-write*)\n"),
    }
    p.push_str("(allow file-write*\n");
    for w in policy.writable() {
        let kind = if w.is_dir() { "subpath" } else { "literal" };
        let _ = writeln!(p, "  ({kind} {})", sbpl_string(w));
    }
    for dev in ["/dev/null", "/dev/zero", "/dev/tty", "/dev/dtracehelper"] {
        let _ = writeln!(p, "  (literal \"{dev}\")");
    }
    p.push_str("  (regex #\"^/dev/ttys[0-9]+$\")\n  (regex #\"^/dev/fd/\"))\n");
    // Create-only: new files and directories may be made and written, but
    // only git's own temporary files may be removed, renamed away or have
    // their mode changed; the objects already there are 0444 and stay so.
    for dir in policy.create_only() {
        let _ = writeln!(
            p,
            "(allow file-write-create file-write-data file-write-times (subpath {}))",
            sbpl_string(dir)
        );
        let tmp = format!("^{}/(.*/)?tmp_[^/]*$", regex_escape(&dir.to_string_lossy()));
        let _ = writeln!(
            p,
            "(allow file-write-unlink file-write-mode file-write-flags file-write-xattr (regex #{}))",
            sbpl_string(Path::new(&tmp))
        );
    }
    p
}

/// `s` with every regex metacharacter escaped, for an SBPL `regex`.
#[cfg(any(target_os = "macos", test))]
fn regex_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        if "\\.+*?()|[]{}^$".contains(c) {
            out.push('\\');
        }
        out.push(c);
    }
    out
}

/// A command that runs `program` with `args` under `policy` through
/// `sandbox-exec`.
#[cfg(target_os = "macos")]
#[must_use]
pub fn seatbelt_command(
    policy: &Policy,
    program: &std::ffi::OsStr,
    args: &[std::ffi::OsString],
) -> std::process::Command {
    let mut cmd = std::process::Command::new(SANDBOX_EXEC);
    cmd.arg("-p")
        .arg(seatbelt_profile(policy))
        .arg(program)
        .args(args);
    cmd
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used)]
    use super::*;

    #[cfg(target_os = "linux")]
    #[test]
    fn enforcement_tracks_required_write_rights_by_abi() {
        use landlock::ABI;

        assert!(matches!(
            enforcement_for_abi(ABI::Unsupported),
            Err(SandboxError::Unsupported)
        ));
        assert_eq!(
            enforcement_for_abi(ABI::V1).unwrap(),
            Enforcement::Partial {
                missing: "Refer (cross-directory rename permissions) and Truncate (file truncation)",
            }
        );
        assert_eq!(
            enforcement_for_abi(ABI::V2).unwrap(),
            Enforcement::Partial {
                missing: "Truncate (file truncation)",
            }
        );
        for abi in [
            ABI::V3,
            ABI::V4,
            ABI::V5,
            ABI::V6,
            ABI::V7,
            ABI::V8,
            ABI::V9,
        ] {
            assert_eq!(
                enforcement_for_abi(abi).unwrap(),
                Enforcement::Full,
                "{abi}"
            );
        }
    }

    #[test]
    fn policies_are_canonical_and_absolute() {
        let dir = tempfile::tempdir().unwrap();
        let p = Policy::new([dir.path(), dir.path()]).unwrap();
        assert_eq!(p.writable(), [dir.path().canonicalize().unwrap()]);
        assert!(matches!(
            Policy::new(["relative"]),
            Err(SandboxError::Relative { .. })
        ));
        assert!(matches!(
            Policy::new([dir.path().join("missing")]),
            Err(SandboxError::Path { .. })
        ));
    }

    #[test]
    fn seatbelt_profiles_escape_paths() {
        let dir = tempfile::tempdir().unwrap();
        let odd = dir.path().join("a \"b\\c");
        std::fs::create_dir(&odd).unwrap();
        let profile = seatbelt_profile(&Policy::new([&odd]).unwrap());
        assert!(profile.starts_with("(version 1)\n(allow default)\n(deny file-write*)\n"));
        assert!(profile.contains(r#"a \"b\\c")"#), "{profile}");
        assert!(profile.contains("(subpath "));
    }

    #[test]
    fn create_only_dirs_allow_new_files_but_only_tmp_removals() {
        let dir = tempfile::tempdir().unwrap();
        let objects = dir.path().join("obj.d+x");
        std::fs::create_dir(&objects).unwrap();
        let policy = Policy::new([dir.path()])
            .unwrap()
            .with_create_only([&objects])
            .unwrap();
        let canonical = objects.canonicalize().unwrap();
        assert_eq!(policy.create_only(), std::slice::from_ref(&canonical));
        let profile = seatbelt_profile(&policy);
        let quoted = sbpl_string(&canonical);
        assert!(
            profile.contains(&format!(
                "(allow file-write-create file-write-data file-write-times (subpath {quoted}))"
            )),
            "{profile}"
        );
        assert!(
            profile.contains(r"obj\\.d\\+x/(.*/)?tmp_[^/]*$"),
            "{profile}"
        );
        assert!(
            !profile.contains(&format!("  (subpath {quoted})")),
            "{profile}"
        );
    }

    #[test]
    fn tagged_profiles_name_the_tag_in_each_denial() {
        let dir = tempfile::tempdir().unwrap();
        let policy = Policy::new([dir.path()])
            .unwrap()
            .tagged("graft-run-ab\"c)12");
        assert_eq!(policy.tag(), Some("graft-run-abc12"));
        let profile = seatbelt_profile(&policy);
        assert!(
            profile.contains("(deny file-write* (with message \"graft-run-abc12\"))\n"),
            "{profile}"
        );
        assert_eq!(Policy::new([dir.path()]).unwrap().tagged("()").tag(), None);
    }

    #[test]
    fn device_files_are_absolute() {
        assert!(DEVICE_FILES.iter().all(|d| d.starts_with("/dev/")));
    }
}
